import {
  Children,
  Fragment,
  isValidElement,
  type ReactNode,
} from 'react'

/**
 * <For each={items} fallback={<Empty />}>
 *   {(item, index) => <Row key={item.id} item={item} />}
 * </For>
 *
 * Renders children for each element of `each`.
 * Falls back to `fallback` (or null) when the array is empty or nullish.
 * Always assigns a React key (from the child, or the index).
 */
interface ForProps<T> {
  each: T[] | null | undefined
  fallback?: ReactNode
  children: (item: T, index: number) => ReactNode
}

export function For<T>({ each, fallback = null, children }: ForProps<T>) {
  if (!Array.isArray(each) || each.length === 0) return <>{fallback}</>

  return (
    <>
      {each.map((item, i) => {
        const node = children(item, i)
        if (isValidElement(node)) {
          return node.key != null ? node : <Fragment key={i}>{node}</Fragment>
        }
        // Arrays / text / multiple nodes from the render prop
        return <Fragment key={i}>{Children.toArray(node)}</Fragment>
      })}
    </>
  )
}

import type React from 'react'

/**
 * <Show when={condition} fallback={<Fallback />}>
 *   {children}
 * </Show>
 *
 * Renders children when `when` is truthy; renders `fallback` (or null) otherwise.
 * When children is a function it receives the truthy value as its first argument —
 * handy for narrowing nullable values without an extra variable.
 */
interface ShowProps<T> {
  when: T | null | undefined | false
  fallback?: React.ReactNode
  children: React.ReactNode | ((value: NonNullable<T>) => React.ReactNode)
}

export function Show<T>({ when, fallback = null, children }: ShowProps<T>) {
  if (!when) return <>{fallback}</>
  return <>{typeof children === 'function' ? children(when as NonNullable<T>) : children}</>
}

import React from 'react'

/**
 * Declarative switch/case component.
 *
 * <Switch value={status}>
 *   <Match when="active">  <ActiveBadge />  </Match>
 *   <Match when="pending"> <PendingBadge /> </Match>
 *   <Match when="banned">  <BannedBadge />  </Match>
 *   <Default>              <UnknownBadge /> </Default>
 * </Switch>
 *
 * - Renders the first <Match> whose `when` strictly equals `value`.
 * - Falls back to the first <Default> child if no match is found.
 * - Both Match and Default are thin wrappers; all logic lives in Switch.
 */

// ── Public components ─────────────────────────────────────────────────────────

interface MatchProps<T> {
  when: T
  children: React.ReactNode
}

/**
 * Represents one case inside a <Switch>. Must be a direct child of <Switch>.
 */
export function Match<T>(_props: MatchProps<T>): React.ReactElement {
  // Rendered by Switch, never directly.
  return <></>
}

interface DefaultProps {
  children: React.ReactNode
}

/**
 * Fallback rendered by <Switch> when no <Match> case applies.
 */
export function Default(_props: DefaultProps): React.ReactElement {
  return <></>
}

// ── Switch ────────────────────────────────────────────────────────────────────

interface SwitchProps<T> {
  value: T
  children: React.ReactNode
}

export function Switch<T>({ value, children }: SwitchProps<T>) {
  const kids = React.Children.toArray(children) as React.ReactElement[]

  for (const child of kids) {
    if (!React.isValidElement(child)) continue

    if (child.type === Match) {
      const props = child.props as MatchProps<T>
      if (props.when === value) return <>{props.children}</>
    }
  }

  // No match — find the first <Default>
  for (const child of kids) {
    if (!React.isValidElement(child)) continue
    if (child.type === Default) {
      return <>{(child.props as DefaultProps).children}</>
    }
  }

  return null
}
